import math

def r(x):
    # Maps x in [0, 1] to sin(x * pi / 2), which is in [0, 1] and >= x.
    return math.sin(x * math.pi / 2.0)

def R(y_orig, y_new):
    # Ensure both outputs are valid probabilities.
    return (
        math.isfinite(y_orig) 
        and math.isfinite(y_new) 
        and 0.0 <= y_orig <= 1.0 
        and 0.0 <= y_new <= 1.0
    )
